using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;
using CodeImp.DoomBuilder.Geometry;
namespace DoomSNESed {
    public sealed class MapCanvas:Control {
        public Map Map;public Rom Rom;public string Mode="Objects";public int Selected=-1,Grid=16;public bool Drawing;
        public readonly HashSet<int> Selection=new HashSet<int>();public Action OnContext;public Action<int> OnSelect;public Action OnEdit;public Action<Point> OnAdd;public Func<bool> OnGeometryEdit;public Func<List<Point>,bool> OnFinish;public Action<string> OnHint;public Action OnToolEnd;
        Dictionary<int,Face> paintFaces;int Near(Wall w){Face f;return paintFaces.TryGetValue(w.Face,out f)?f.Near:-1;}int Far(Wall w){Face f;return paintFaces.TryGetValue(w.Face,out f)?f.Far:-1;}readonly List<Point> outline=new List<Point>();float zoom=.15f,cx,cy;bool pan,drag;System.Drawing.Point last;Point hover=new Point();
        public MapCanvas(){DoubleBuffered=true;BackColor=Theme.Background;Dock=DockStyle.Fill;SetStyle(ControlStyles.Selectable,true);TabStop=true;}
        public void Fit(){if(Map==null||Map.Vertices.Count==0){cx=cy=0;zoom=.5f;Invalidate();return;}int x0=Map.Vertices.Min(p=>p.X),x1=Map.Vertices.Max(p=>p.X),y0=Map.Vertices.Min(p=>p.Y),y1=Map.Vertices.Max(p=>p.Y);cx=(x0+x1)/2f;cy=(y0+y1)/2f;zoom=Math.Max(.015f,Math.Min((Width-100f)/Math.Max(1,x1-x0),(Height-110f)/Math.Max(1,y1-y0)));Invalidate();}
        public void CancelOutline(){outline.Clear();Invalidate();}
        PointF Screen(Point p){return new PointF(Width/2f+(p.X-cx)*zoom,Height/2f-(p.Y-cy)*zoom);}
        Point World(int x,int y){return new Point((int)(cx+(x-Width/2f)/zoom),(int)(cy-(y-Height/2f)/zoom));}
        Point Snap(Point p){Point snapped=new Point((int)Math.Round((double)p.X/Grid)*Grid,(int)Math.Round((double)p.Y/Grid)*Grid);if(Map==null)return snapped;Point nearest=null;double distance=100/(zoom*zoom);for(int i=0;i<Map.Vertices.Count;i++){if(drag&&Mode=="Vertices"&&i==Selected)continue;Point v=Map.Vertices[i];double d=(v.Vec-p.Vec).GetLengthSq();if(d<distance){distance=d;nearest=v;}}if(nearest!=null&&(nearest.Vec-p.Vec).GetLengthSq()<100/(zoom*zoom))return new Point(nearest.X,nearest.Y);return snapped;}
        public void Finish(){if(outline.Count<2)return;if(OnFinish!=null&&OnFinish(outline.Select(p=>new Point(p.X,p.Y)).ToList()))outline.Clear();Invalidate();}
        GraphicsPath SectorPath(int sector){var path=new GraphicsPath(FillMode.Alternate);var edges=new List<Tuple<int,int>>();foreach(Wall w in Map.Walls){if(Near(w)==sector)edges.Add(Tuple.Create(w.Start,w.End));if(Far(w)==sector)edges.Add(Tuple.Create(w.End,w.Start));}
            while(edges.Count>0){var first=edges[0];edges.RemoveAt(0);var points=new List<PointF>{Screen(Map.Vertices[first.Item1])};int current=first.Item2,guard=0;while(current!=first.Item1&&guard++<Map.Walls.Count+1){points.Add(Screen(Map.Vertices[current]));var next=edges.FirstOrDefault(t=>t.Item1==current);if(next==null)break;edges.Remove(next);current=next.Item2;}if(points.Count>=3)path.AddPolygon(points.ToArray());}return path;
        }
        PointF? SectorLabelPoint(GraphicsPath path){if(path.PointCount==0)return null;var bounds=RectangleF.Intersect(path.GetBounds(),new RectangleF(0,36,Width,Math.Max(0,Height-79)));if(bounds.Width<=0||bounds.Height<=0)return null;var center=new PointF(bounds.Left+bounds.Width/2,bounds.Top+bounds.Height/2);if(path.IsVisible(center))return center;PointF? best=null;float distance=float.MaxValue;for(int y=0;y<9;y++)for(int x=0;x<9;x++){var p=new PointF(bounds.Left+(x+.5f)*bounds.Width/9,bounds.Top+(y+.5f)*bounds.Height/9);float d=(p.X-center.X)*(p.X-center.X)+(p.Y-center.Y)*(p.Y-center.Y);if(d<distance&&path.IsVisible(p)){best=p;distance=d;}}return best;}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;
            using(var fill=new LinearGradientBrush(ClientRectangle,Color.FromArgb(11,26,20),Theme.Background,90f))g.FillRectangle(fill,ClientRectangle);
            if(Map==null){using(var font=new Font("Segoe UI",20))using(var brush=new SolidBrush(Theme.Text))g.DrawString("Your next SNES level starts here",font,brush,35,65);using(var brush=new SolidBrush(Theme.Muted))g.DrawString("Open your Doom ROM, then choose New map or select a level on the left.",Font,brush,37,115);return;}
            paintFaces=Map.Faces.ToDictionary(f=>f.Offset);int step=Grid;while(step*zoom<18)step*=2;Point lo=World(0,Height),hi=World(Width,0);
            using(var pen=new Pen(Color.FromArgb(30,50,39))){for(int x=(int)Math.Floor((double)lo.X/step)*step;x<=hi.X;x+=step){float sx=Screen(new Point(x,0)).X;g.DrawLine(pen,sx,0,sx,Height);}for(int y=(int)Math.Floor((double)lo.Y/step)*step;y<=hi.Y;y+=step){float sy=Screen(new Point(0,y)).Y;g.DrawLine(pen,0,sy,Width,sy);}}
            var sectorLabels=new List<Tuple<PointF,int>>();
            for(int s=0;s<Map.Sectors.Count;s++)using(var path=SectorPath(s))using(var brush=new SolidBrush(Mode=="Sectors"&&Selection.Contains(s)?Color.FromArgb(80,123,197,109):Map.Sectors[s].Motion==SectorMotion.Door?Color.FromArgb(35,213,166,63):Map.Sectors[s].Motion==SectorMotion.Lift?Color.FromArgb(38,60,165,150):Color.FromArgb(13,95,164,119))){g.FillPath(brush,path);if(Mode=="Sectors"){var point=SectorLabelPoint(path);var bounds=path.GetBounds();if(point.HasValue&&(s==Selected||bounds.Width>=28&&bounds.Height>=18))sectorLabels.Add(Tuple.Create(point.Value,s));}}
            for(int i=0;i<Map.Walls.Count;i++){Wall w=Map.Walls[i];PointF a=Screen(Map.Vertices[w.Start]),b=Screen(Map.Vertices[w.End]);bool selected=(Mode=="Walls"&&Selection.Contains(i))||(Mode=="Surfaces"&&Selected>=0&&Selected<Map.Faces.Count&&(Map.Faces[Selected].Offset==w.Face||Map.Faces[Selected].Offset==w.BackFace));
                Color colour=selected?Theme.Accent:w.Type==11||w.Type==51||w.Type==52?Color.FromArgb(238,133,94):(w.Flags&16)!=0?Color.FromArgb(219,184,100):Far(w)>=0?Color.FromArgb(66,124,101):Color.FromArgb(171,204,176);
                using(var pen=new Pen(colour,selected?2.7f:1.3f)){g.DrawLine(pen,a,b);if(Mode=="Walls"||selected){float dx=b.X-a.X,dy=b.Y-a.Y,len=(float)Math.Sqrt(dx*dx+dy*dy);if(len>15)g.DrawLine(pen,(a.X+b.X)/2,(a.Y+b.Y)/2,(a.X+b.X)/2-dy/len*6,(a.Y+b.Y)/2+dx/len*6);}}
            }
            if(Mode=="Vertices"||Drawing)for(int i=0;i<Map.Vertices.Count;i++){PointF p=Screen(Map.Vertices[i]);bool selected=Mode=="Vertices"&&Selected==i;using(var brush=new SolidBrush(selected?Theme.Accent:Theme.Mint))g.FillRectangle(brush,p.X-2.5f,p.Y-2.5f,5,5);}
            for(int i=0;i<Map.Things.Count;i++){Thing t=Map.Things[i];PointF p=Screen(new Point(t.X,t.Y));bool selected=Mode=="Objects"&&Selected==i;Color c=selected?Theme.Accent:t.Type==0?Theme.Mint:t.Type>=6&&t.Type<=14?Color.FromArgb(228,116,99):Color.FromArgb(122,176,219);float r=selected?7:4;using(var pen=new Pen(c,selected?2:1)){g.DrawEllipse(pen,p.X-r,p.Y-r,r*2,r*2);if(t.Type==0){double angle=t.Angle*Math.PI*2/65536;g.DrawLine(pen,p.X,p.Y,p.X+(float)Math.Cos(angle)*17,p.Y-(float)Math.Sin(angle)*17);}}}
            var labelBoxes=new List<RectangleF>();foreach(var label in sectorLabels.OrderByDescending(l=>l.Item2==Selected)){string text="#"+label.Item2;SizeF size=g.MeasureString(text,Font);var box=new RectangleF(label.Item1.X-size.Width/2-3,label.Item1.Y-size.Height/2,size.Width+6,size.Height);if(labelBoxes.Any(b=>b.IntersectsWith(box)))continue;labelBoxes.Add(box);using(var background=new SolidBrush(Color.FromArgb(225,12,30,23)))g.FillRectangle(background,box);using(var foreground=new SolidBrush(label.Item2==Selected?Theme.Accent:Theme.Mint))g.DrawString(text,Font,foreground,box.X+3,box.Y);}
            if(outline.Count>0){using(var pen=new Pen(Theme.Accent,2)){for(int i=0;i<outline.Count;i++){PointF p=Screen(outline[i]);g.FillEllipse(Brushes.PaleGreen,p.X-3,p.Y-3,6,6);if(i>0)g.DrawLine(pen,Screen(outline[i-1]),p);}pen.DashStyle=DashStyle.Dash;g.DrawLine(pen,Screen(outline[outline.Count-1]),Screen(hover));}}
            using(var brush=new SolidBrush(Color.FromArgb(220,12,30,23)))g.FillRectangle(brush,0,0,Width,36);
            using(var brush=new SolidBrush(Theme.Mint))g.DrawString(Map.Name+"   /   "+(Map.EditGeometry?"Editable geometry":Map.NewRoom?"Room template":"Original ROM map")+"   /   Grid "+Grid+"   /   "+(Drawing?"DRAW SECTORS & LINES":Mode=="Objects"?"Things":Mode)+(Mode=="Sectors"&&Selected>=0?"   /   Internal sector #"+Selected+" (0-based)":""),Font,brush,13,10);
            string hint=Drawing?"Click outline points; close at the first point or Enter. Two points + Enter split a sector. Esc cancels; Backspace removes a point.":Mode=="Vertices"?"Drag vertices to shape the level. Arrows / middle drag pan; wheel zooms. D draws; F3 opens the 3D view.":Mode=="Sectors"?"Click a sector, then edit its heights, floor type or motion on the right. D draws; F3 opens the 3D view.":"Ctrl+click selects multiple lines/sectors; right-click edits. Arrows pan; drag things to move. Double-click adds a thing. D draws sectors/lines; F3 opens the 3D view.";
            using(var brush=new SolidBrush(Color.FromArgb(220,12,30,23)))g.FillRectangle(brush,0,Height-43,Width,43);using(var font=new Font("Segoe UI",9))using(var brush=new SolidBrush(Theme.Muted))g.DrawString(hint,font,brush,new RectangleF(12,Height-37,Width-24,35));
        }
        protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Focus();last=e.Location;if(Map==null)return;if(e.Button==MouseButtons.Middle||(e.Button==MouseButtons.Right&&Mode!="Walls"&&Mode!="Sectors")){pan=true;Capture=true;return;}
            Point p=World(e.X,e.Y);if(Drawing&&e.Button==MouseButtons.Left){hover=Snap(p);if(outline.Count>=3&&GeometryTools.Same(hover,outline[0]))Finish();else if(outline.Count==0||!GeometryTools.Same(outline[outline.Count-1],hover))outline.Add(hover);Invalidate();return;}
            int selected=-1;double best=144/(zoom*zoom);
            if(Mode=="Objects"){for(int i=0;i<Map.Things.Count;i++){Thing t=Map.Things[i];double d=(new Vector2D(t.X,t.Y)-p.Vec).GetLengthSq();if(d<best){best=d;selected=i;}}drag=selected>=0;}
            else if(Mode=="Vertices"){for(int i=0;i<Map.Vertices.Count;i++){double d=(Map.Vertices[i].Vec-p.Vec).GetLengthSq();if(d<best){best=d;selected=i;}}if(selected>=0)drag=OnGeometryEdit==null||OnGeometryEdit();}
            else if(Mode=="Sectors")selected=GeometryTools.SectorAt(Map,p);
            else for(int i=0;i<Map.Walls.Count;i++){Wall w=Map.Walls[i];double d=Line2D.GetDistanceToLineSq(Map.Vertices[w.Start].Vec,Map.Vertices[w.End].Vec,p.Vec,true);if(d<best){best=d;selected=Mode=="Surfaces"?Map.Faces.FindIndex(f=>f.Offset==w.Face):i;}}
            if((ModifierKeys&Keys.Control)!=0&&e.Button==MouseButtons.Left&&(Mode=="Walls"||Mode=="Sectors")){if(!Selection.Add(selected))Selection.Remove(selected);Selection.Remove(-1);}else if(!(e.Button==MouseButtons.Right&&Selection.Contains(selected))){Selection.Clear();if(selected>=0)Selection.Add(selected);}Selected=selected;Capture=drag;if(OnSelect!=null)OnSelect(selected);if(e.Button==MouseButtons.Right&&selected>=0&&OnContext!=null)OnContext();Invalidate();
        }
        protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(Map==null)return;if(pan){cx-=(e.X-last.X)/zoom;cy+=(e.Y-last.Y)/zoom;Invalidate();}hover=Snap(World(e.X,e.Y));
            if(drag&&Selected>=0){if(Mode=="Objects"){Thing t=Map.Things[Selected];t.X=hover.X;t.Y=hover.Y;}else if(Mode=="Vertices"){Map.Vertices[Selected].X=hover.X;Map.Vertices[Selected].Y=hover.Y;}Invalidate();}
            if(Drawing)Invalidate();last=e.Location;if(OnHint!=null)OnHint("X "+hover.X+"   Y "+hover.Y+"   /   Grid "+Grid);
        }
        protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);bool changed=drag;pan=drag=false;Capture=false;if(changed&&OnEdit!=null)OnEdit();}
        protected override void OnMouseWheel(MouseEventArgs e){base.OnMouseWheel(e);Point before=World(e.X,e.Y);zoom=Math.Max(.01f,Math.Min(5,zoom*(e.Delta>0?1.2f:1/1.2f)));Point after=World(e.X,e.Y);cx+=before.X-after.X;cy+=before.Y-after.Y;Invalidate();}
        protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);if(Drawing){Finish();return;}if(Map!=null&&Mode=="Objects"&&e.Button==MouseButtons.Left&&OnAdd!=null)OnAdd(Snap(World(e.X,e.Y)));}
        protected override bool IsInputKey(Keys keyData){return (keyData&Keys.KeyCode)==Keys.Left||(keyData&Keys.KeyCode)==Keys.Right||(keyData&Keys.KeyCode)==Keys.Up||(keyData&Keys.KeyCode)==Keys.Down||keyData==Keys.Enter||keyData==Keys.Escape||keyData==Keys.Back||base.IsInputKey(keyData);}
        protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right||e.KeyCode==Keys.Up||e.KeyCode==Keys.Down){float amount=Math.Max(Grid,48/zoom)*(e.Shift?4:1);if(e.KeyCode==Keys.Left)cx-=amount;if(e.KeyCode==Keys.Right)cx+=amount;if(e.KeyCode==Keys.Up)cy+=amount;if(e.KeyCode==Keys.Down)cy-=amount;Invalidate();e.Handled=true;e.SuppressKeyPress=true;return;}if(Drawing&&e.KeyCode==Keys.Enter){Finish();e.Handled=true;}else if(Drawing&&e.KeyCode==Keys.Escape){if(outline.Count>0)outline.Clear();else{Drawing=false;if(OnToolEnd!=null)OnToolEnd();}Invalidate();e.Handled=true;}else if(Drawing&&e.KeyCode==Keys.Back&&outline.Count>0){outline.RemoveAt(outline.Count-1);Invalidate();e.Handled=true;}}
    }
}
